<?php
declare(strict_types=1);require __DIR__.'/includes/bootstrap.php';require __DIR__.'/includes/auth.php';require_once __DIR__.'/includes/pdf_documents.php';require_permission('contracts.view');
$pageTitle='Contratos de servicio';$q=trim((string)($_GET['q']??''));$status=(string)($_GET['status']??'all');$where=[];$params=[];if($q!==''){$where[]='(ct.contract_number LIKE ? OR ct.title LIKE ? OR c.company_name LIKE ? OR c.country LIKE ?)';$like='%'.$q.'%';array_push($params,$like,$like,$like,$like);}if(in_array($status,['draft','sent','approved','rejected','signed','cancelled'],true)){$where[]='ct.status=?';$params[]=$status;}$sql='SELECT ct.*,c.company_name,c.country FROM contracts ct JOIN clients c ON c.id=ct.client_id'.($where?' WHERE '.implode(' AND ',$where):'').' ORDER BY ct.created_at DESC';$stmt=db()->prepare($sql);$stmt->execute($params);$rows=$stmt->fetchAll();require __DIR__.'/includes/header.php';?>
<section class="panel"><div class="panel-header"><div><h2>Contratos enviados a clientes</h2><span class="table-sub">Crea documentos completos desde plantillas profesionales, edítalos y expórtalos en Word o PDF, imprímelos y envíalos por email para aprobación.</span></div><div class="actions"><?php if(has_permission('contract_templates.view')):?><a class="btn btn-light" href="contract_templates.php">PLANTILLAS</a><?php endif;?><?php if(has_permission('contracts.create')):?><a class="btn btn-primary" href="contract_form.php">+ CREAR CONTRATO</a><?php endif;?></div></div><div class="panel-body"><form class="filters" method="get"><input name="q" value="<?=e($q)?>" placeholder="Número, título, cliente o país"><select name="status"><option value="all">Todos los estados</option><?php foreach(['draft','sent','approved','rejected','signed','cancelled']as$s):?><option value="<?=$s?>" <?=$status===$s?'selected':''?>><?=e(contract_status_label($s))?></option><?php endforeach;?></select><button class="btn btn-secondary btn-small">FILTRAR</button></form></div><div class="table-wrap"><?php if(!$rows):?><div class="empty">No hay contratos.</div><?php else:?><table class="data-table"><thead><tr><th>Contrato</th><th>Cliente</th><th>Idioma</th><th>Fecha</th><th>Estado</th><th>Acciones</th></tr></thead><tbody><?php foreach($rows as$row):?><tr><td><a class="table-title" href="contract_view.php?id=<?=(int)$row['id']?>"><?=e($row['contract_number'])?></a><span class="table-sub"><?=e($row['title'])?></span></td><td><?=e(($row['country']?:'Sin país').' · '.$row['company_name'])?></td><td><?=e(language_label($row['language']))?></td><td><?=e(format_date($row['issue_date']))?></td><td><span class="badge badge-<?=e(contract_status_class($row['status']))?>"><?=e(contract_status_label($row['status']))?></span></td><td><div class="actions"><a class="btn btn-light btn-small" href="contract_view.php?id=<?=(int)$row['id']?>">Abrir</a><a class="icon-action" title="Word" aria-label="Descargar Word" href="contract_word.php?id=<?=(int)$row['id']?>"><?=crm_icon('contract')?></a><a class="icon-action" title="PDF" aria-label="Descargar PDF" href="contract_pdf.php?id=<?=(int)$row['id']?>"><?=crm_icon('download')?></a><?php if(has_permission('contracts.edit')&&in_array($row['status'],['draft','rejected'],true)):?><a class="btn btn-secondary btn-small" href="contract_form.php?id=<?=(int)$row['id']?>">Editar</a><?php endif;?></div></td></tr><?php endforeach;?></tbody></table><?php endif;?></div></section><?php require __DIR__.'/includes/footer.php';?>
